insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('toucan-protocol','Toucan Protocol','descartada','Registro bloqueado','El bloqueo no viene de Toucan, sino de los registros de carbono: en mayo de 2022, Verra prohibió tokenizar créditos ya retirados y el American Carbon Registry prohibió tokenizar los suyos sin su autorización expresa. Verra estudiaba entonces un estado «inmovilizado» que permitiría tokenizarlos. Toucan respaldó públicamente la decisión de Verra.','2026-08-06');
